import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百四十一章 扔到空中的棍子","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/141第一百四十一章 扔到空中的棍子.md","filePath":"meditation/巴利文大藏经/141第一百四十一章 扔到空中的棍子.md"}'),_={name:"meditation/巴利文大藏经/141第一百四十一章 扔到空中的棍子.md"};function o(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百四十一章-扔到空中的棍子",tabindex:"-1"},[l("第一百四十一章 扔到空中的棍子 "),e("a",{class:"header-anchor",href:"#第一百四十一章-扔到空中的棍子","aria-label":'Permalink to "第一百四十一章 扔到空中的棍子"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部15相应9经/棍子经(无始相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，生死轮回是永无止境的，是无穷无尽的，不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回是循环不止的，他们无法知道自己生死轮回的起点在什么地方。",-1),e("p",null,"弟子们，就如同将一根棍子扔到空中，这根棍子有的时候头部着地，有的时候尾部着地，有的时候整个棍子横着、平着落到地上。弟子们，同样的道理，这些不明白世间真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们在无穷无尽、永无止境的生死轮回中，有的时候从这个世界生到那个世界，有的时候又从那个世界生到这个世界；有的时候从这个世界生到其他世界，有的时候又从其他世界生到这个世界，他们这样无数次的出生到不同的世界里。",-1),e("p",null,"这是为什么呢？弟子们，因为生死轮回是永无止境的，是无穷无尽的！所以你们投生的世界也是永无止境、无穷无尽的。这些不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回也是循环不止的，也是无穷无尽的，他们也是无法知道他们自己生死轮回的起点在什么地方的。",-1),e("p",null,"弟子们，你们无数次的生死轮回，无数次的承受痛苦，无数次的经历不幸，无数次的忧愁、悲伤、苦闷、忧虑、绝望。无数次的死后埋入墓地。弟子们，你们要从世间解脱出来，要从生死轮回中解脱出来，就不要再挂念和执着世间一切的事物，就不要再执着和挂念自己一切的行为、言语、念想。这样你们就不会被世间一切的事物束缚捆绑，这样你们就不会被自己的行为、言语、念想束缚捆绑。这样你们就能最终从生死轮回中永远的解脱出来。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(_,[["render",o]]);export{u as __pageData,f as default};
